import importlib.metadata,json,platform,sys; packages=["numpy","scipy","statsmodels","pydantic","pytest","dowhy","econml"]; versions={};
for name in packages:
 try: versions[name]=importlib.metadata.version(name)
 except importlib.metadata.PackageNotFoundError: versions[name]="not_installed"
print(json.dumps({"python":sys.version,"executable":sys.executable,"platform":platform.platform(),"packages":versions},indent=2))
